/// <reference types="vite/client" />

// Allow importing PDF, JPG, PNG files as Vite asset URLs
declare module "*.pdf" {
  const src: string;
  export default src;
}

declare module "*.jpg" {
  const src: string;
  export default src;
}

declare module "*.jpeg" {
  const src: string;
  export default src;
}

declare module "*.png" {
  const src: string;
  export default src;
}
